import { query } from "@anthropic-ai/claude-agent-sdk";

const session = query({
  prompt: "Reply with the single word: pong",
  options: {
    model: "claude-haiku-5-5",
    effort: "low",
    tools: [],
    settingSources: [],
  },
});

for await (const msg of session) {
  if (msg.type === "system" && msg.subtype === "init") {
    console.log("init", msg.model, msg.claude_code_version);
  } else if (msg.type === "assistant") {
    console.log("assistant", JSON.stringify(msg.message.content));
  } else if (msg.type === "result") {
    console.log("result", msg.subtype, "is_error", msg.is_error, "turns", msg.num_turns);
    console.log("cost", msg.total_cost_usd, "models", Object.keys(msg.modelUsage));
    console.log("session", msg.session_id);
    if (msg.subtype === "success") console.log("said", msg.result);
  }
}

import type { SDKResultMessage } from "@anthropic-ai/claude-agent-sdk";

export const report = (msg: SDKResultMessage) => {
  const cost = Object.values(msg.modelUsage).reduce((sum, m) => sum + m.costUSD, 0);
  if (msg.subtype !== "success") return `STOPPED (${msg.subtype}) after ${msg.num_turns} turns, $${cost.toFixed(4)}`;
  if (msg.is_error) return `FAILED: ${msg.result}`;
  return `OK in ${msg.num_turns} turns, $${cost.toFixed(4)}, session ${msg.session_id}`;
};

